const VARIANTS = {
  /** the figure only: favicons, small badges, posters' corner */
  symbol: { viewBox: '859.8 399.0 229.2 281.3', ratio: 0.8151, parts: [SYMBOL] },
  /** figure + "המשך תנועה": headers and navigation */
  lockup: { viewBox: '513.4 399.0 575.6 281.3', ratio: 2.0464, parts: [SYMBOL, TITLE] },
  /** figure + name + "הבית ללוחמים.ות באזרחות": public pages, print, posters */
  full: { viewBox: '483.0 399.0 606.0 281.4', ratio: 2.1534, parts: [SYMBOL, TITLE, TAGLINE] },
} as const;

export type LogoVariant = keyof typeof VARIANTS;

/**
 * Brand logo. `height` in px (number) or any CSS length such as '3em'; width follows the official proportions.
 * Decorative unless `label` is given.
 */
export function Logo({ variant = 'lockup', height = 40, label, className }: { variant?: LogoVariant; height?: number | string; label?: string; className?: string }) {
  const v = VARIANTS[variant];
  const size = typeof height === 'number'
    ? { height, width: Math.round(height * v.ratio) }
    : { style: { height, width: `calc(${height} * ${v.ratio.toFixed(4)})` } };
  return (
    <svg
      viewBox={v.viewBox}
      {...size}
      fill="currentColor"
      className={className}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      {v.parts.flat().map(([rule, d], i) => <path key={i} fillRule={rule} d={d} />)}
    </svg>
  );
}

/** Raw path data for canvas drawing (posters, stories): same source as the component. */
export const LOGO_PATHS = { SYMBOL, TITLE, TAGLINE, VARIANTS };
